    parser.runtime["events"] = events
    parser.runtime["osc_adapter"] = osc_adapter
    parser.runtime["q_profile"] = "default"
    parser.runtime["q_chat_symbol"] = "$CH:q"

    run_boot_hooks(state, flags)

    trigger_loop.start()
    event_loop.start()
    osc_server.start()

    return ctx
