from pathlib import Path

from system.cs.lib.ops import list_symbols, remove_subtree, validate_symbol

_SYMBOL_ROOTS = "$#&%@!"

_DEFAULT_IGNORE_PATTERNS = [
    "__pycache__",
    "*.pyc",
    "*.pyo",
    "*.sqlite",
    "*.db",
    ".DS_Store",
    "Thumbs.db",
    ".git",
    ".venv",
    "node_modules",
