    def stop(self) -> None:
        self._running = False

    def run(self) -> None:
        while self._running:
            try:
                name = self.bus.get(timeout=0.1)
            except Empty:
                continue

            try:
                self.runtime.emit_trigger(name, self.parser)
            except Exception as exc:
                print(f"[event-error] {type(exc).__name__}: {exc}")
